import{_ as p,a0 as o,w as r,s as d,ao as l,I as n,x as a,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"怎樣在 ubuntu 和 debian 中通過命令列管理 KVM | LCTT x X-CMD","titleTemplate":false,"description":"怎樣在 ubuntu 和 debian 中通過命令列管理 KVM | LCTT (201602) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎樣在 ubuntu 和 debian 中通過命令列管理 KVM | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎樣在 ubuntu 和 debian 中通過命令列管理 KVM | LCTT (201602) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201602/20160104 How to use KVM from the command line on Debian or Ubuntu","title":"怎樣在 ubuntu 和 debian 中通過命令列管理 KVM","tag":"201602","desc":""},"relativePath":"201602/20160104 How to use KVM from the command line on Debian or Ubuntu.md","filePath":"[post].md"}'),h={name:"201602/20160104 How to use KVM from the command line on Debian or Ubuntu.md"};function c(g,s,u,b,k,m){const i=o("Link");return r(),d("div",null,[s[18]||(s[18]=l(`<h1 id="怎樣在-ubuntu-和-debian-中通過命令列管理-kvm" tabindex="-1">怎樣在 ubuntu 和 debian 中通過命令列管理 KVM <a class="header-anchor" href="#怎樣在-ubuntu-和-debian-中通過命令列管理-kvm" aria-label="Permalink to “怎樣在 ubuntu 和 debian 中通過命令列管理 KVM”">​</a></h1><p>有很多不同的方式去管理運行在 KVM 管理程序上的虛擬機。例如，virt-manager 就是一個流行的基於圖形界面的前端虛擬機管理工具。然而，如果你想要在沒有圖形窗口的服務器環境下使用 KVM ，那麼基於圖形界面的解決方案顯然是行不通的。事實上，你可以單純使用包裝了 kvm 命令列腳本的命令列來管理 KVM 虛擬機。作為替代方案，你可以使用 virsh 這個容易使用的命令列程序來管理客户虛擬機。在 virsh 中，它通過和 libvirtd 服務通信來達到控制虛擬機的目的，而 libvirtd 可以控制多個不同的虛擬機管理器，包括 KVM，Xen，QEMU，LXC 和 OpenVZ。</p><p>當你想要對虛擬機的前期準備和後期管理實現自動化操作時，像 virsh 這樣的命令列管理工具是非常有用的。同樣，virsh 支持多個管理器也就意味着你可以通過相同的 virsh 接口去管理不同的虛擬機管理器。</p><p>在這篇文章中，我會示範<strong>怎樣在 ubuntu 和 debian 上通過使用 virsh 命令列去運行 KVM</strong>。</p><h3 id="第一步-確認你的硬件平台支持虛擬化" tabindex="-1">第一步：確認你的硬件平台支持虛擬化 <a class="header-anchor" href="#第一步-確認你的硬件平台支持虛擬化" aria-label="Permalink to “第一步：確認你的硬件平台支持虛擬化”">​</a></h3><p>第一步，首先要確認你的 CPU 支持硬件虛擬化擴展（e.g.，Intel VT 或者 AMD-V)，這是 KVM 對硬件的要求。下面的命令可以檢查硬件是否支持虛擬化。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ egrep &#39;(vmx|svm)&#39; --color /proc/cpuinfo</span></span></code></pre></div><p><img src="https://c2.staticflickr.com/2/1505/24050288606_758a44c4c6_c.jpg" alt=""></p><p>如果在輸出中不包含 vmx 或者 svm 標識，那麼就意味着你的 cpu 不支持硬件虛擬化。因此你不能在你的機器上使用 KVM 。確認了 cpu 支持 vmx 或者 svm 之後，接下來開始安裝 KVM。</p><p>對於 KVM 來説，它不要求運行在擁有 64 位內核系統的主機上，但是通常我們會推薦在 64 位系統的主機上面運行 KVM。</p><h3 id="第二步-安裝kvm" tabindex="-1">第二步：安裝KVM <a class="header-anchor" href="#第二步-安裝kvm" aria-label="Permalink to “第二步：安裝KVM”">​</a></h3><p>使用 <code>apt-get</code> 安裝 KVM 和相關的用户空間工具。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ sudo apt-get install qemu-kvm libvirt-bin</span></span></code></pre></div><p>安裝期間，libvirtd 用户組（在 debian 上是 libvirtd-qemu 用户組）將會被創建，並且你的用户 id 將會被自動添加到該組中。這樣做的目的是讓你可以以一個普通用户而不是 root 用户的身份去管理虛擬機。你可以使用 <code>id</code> 命令來確認這一點，下面將會告訴你怎麼去顯示你的組 id：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ id &lt;your-userID&gt;</span></span></code></pre></div><p><img src="https://c2.staticflickr.com/6/5597/15432586092_64dfb867d3_c.jpg" alt=""></p><p>如果因為某些原因，libvirt（在 debian 中是 libvirt-qemu）沒有在你的組 id 中被找到，你也可以手動將你自己添加到對應的組中，如下所示：</p><p>在 ubuntu 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ sudo adduser [youruserID] libvirtd</span></span></code></pre></div><p>在 debian 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ sudo adduser [youruserID] libvirt-qemu</span></span></code></pre></div><p>按照如下命令重新載入更新後的組成員關係。如果要求輸入密碼，那麼輸入你的登陸密碼即可。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ exec su -l $USER</span></span></code></pre></div><p>這時，你應該可以以普通用户的身份去執行 virsh 了。做一個如下所示的測試，這個命令將會以列表的形式列出可用的虛擬機（當前的列表是空的）。如果你沒有遇到權限問題，那意味着到目前為止一切都是正常的。</p><pre><code>$ virsh list
</code></pre><hr><pre><code> Id    Name                           State
</code></pre><hr><h3 id="第三步-配置橋接網絡" tabindex="-1">第三步：配置橋接網絡 <a class="header-anchor" href="#第三步-配置橋接網絡" aria-label="Permalink to “第三步：配置橋接網絡”">​</a></h3><p>為了使 KVM 虛擬機能夠訪問外部網絡，一種方法是通過在 KVM 宿主機上創建 Linux 橋來實現。創建之後的橋能夠將虛擬機的虛擬網卡和宿主機的物理網卡連接起來，因此，虛擬機能夠發送和接收由物理網卡傳輸的數據包。這種方式叫做網絡橋接。</p><p>下面將告訴你如何創建並且配置網橋，我們創建一個網橋稱它為 br0。</p><p>首先，安裝一個必需的包，然後用命令列創建一個網橋。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ sudo apt-get install bridge-utils</span></span>
<span class="line"><span>    $ sudo brctl addbr br0</span></span></code></pre></div>`,33)),n("p",null,[s[1]||(s[1]=a("下一步就是配置已經創建好的網橋，即修改位於 ",-1)),s[2]||(s[2]=n("code",null,"/etc/network/interfaces",-1)),s[3]||(s[3]=a(" 的配置文件。我們需要將該橋接網卡設置成開機啓動。為了修改該配置文件，你需要關閉你的操作系統上的網絡管理器（如果你在使用它的話）。跟隨",-1)),e(i,{href:"http://xmodulo.com/disable-network-manager-linux.html"},{default:t(()=>[...s[0]||(s[0]=[a("操作指南",-1)])]),_:1}),s[4]||(s[4]=a("的説明去關閉網絡管理器。",-1))]),s[19]||(s[19]=l(`<p>關閉網絡管理器之後，接下來就是通過修改配置文件來配置網橋了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    #auto eth0</span></span>
<span class="line"><span>    #iface eth0 inet dhcp</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    auto br0</span></span>
<span class="line"><span>    iface br0 inet dhcp</span></span>
<span class="line"><span>            bridge_ports eth0</span></span>
<span class="line"><span>            bridge_stp off</span></span>
<span class="line"><span>            bridge_fd 0</span></span>
<span class="line"><span>            bridge_maxwait 0</span></span></code></pre></div><p>在上面的配置中，我假設 eth0 是主要網卡，它也是連接到外網的網卡，同樣，我假設 eth0 將會通過 DHCP 協議自動獲取 ip 地址。注意，之前在 <code>/etc/network/interfaces</code> 中還沒有對 eth0 進行任何配置。橋接網卡 br0 引用了 eth0 的配置，而 eth0 也會受到 br0 的制約。</p><p>重啓網絡服務，並確認網橋已經被成功的配置好。如果成功的話，br0 的 ip 地址將會是 eth0 自動分配的 ip 地址，而且 eth0 不會被分配任何 ip 地址。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ sudo /etc/init.d/networking restart</span></span>
<span class="line"><span>    $ ifconfig</span></span></code></pre></div><p>如果因為某些原因，eth0 仍然保留了之前分配給了 br0 的 ip 地址，那麼你可能必須手動刪除 eth0 的 ip 地址。</p><p><img src="https://c2.staticflickr.com/2/1698/23780708850_66cd7ba6ea_c.jpg" alt=""></p><h3 id="第四步-用命令列創建一個虛擬機" tabindex="-1">第四步：用命令列創建一個虛擬機 <a class="header-anchor" href="#第四步-用命令列創建一個虛擬機" aria-label="Permalink to “第四步：用命令列創建一個虛擬機”">​</a></h3><p>對於虛擬機來説，它的配置信息被存儲在它對應的xml文件中。因此，創建一個虛擬機的第一步就是準備一個與虛擬機對應的 xml 文件。</p><p>下面是一個示例 xml 文件，你可以根據需要手動修改它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    &lt;domain type=&#39;kvm&#39;&gt;</span></span>
<span class="line"><span>      &lt;name&gt;alice&lt;/name&gt;</span></span>
<span class="line"><span>      &lt;uuid&gt;f5b8c05b-9c7a-3211-49b9-2bd635f7e2aa&lt;/uuid&gt;</span></span>
<span class="line"><span>      &lt;memory&gt;1048576&lt;/memory&gt;</span></span>
<span class="line"><span>      &lt;currentMemory&gt;1048576&lt;/currentMemory&gt;</span></span>
<span class="line"><span>      &lt;vcpu&gt;1&lt;/vcpu&gt;</span></span>
<span class="line"><span>      &lt;os&gt;</span></span>
<span class="line"><span>        &lt;type&gt;hvm&lt;/type&gt;</span></span>
<span class="line"><span>        &lt;boot dev=&#39;cdrom&#39;/&gt;</span></span>
<span class="line"><span>      &lt;/os&gt;</span></span>
<span class="line"><span>      &lt;features&gt;</span></span>
<span class="line"><span>        &lt;acpi/&gt;</span></span>
<span class="line"><span>      &lt;/features&gt;</span></span>
<span class="line"><span>      &lt;clock offset=&#39;utc&#39;/&gt;</span></span>
<span class="line"><span>      &lt;on_poweroff&gt;destroy&lt;/on_poweroff&gt;</span></span>
<span class="line"><span>      &lt;on_reboot&gt;restart&lt;/on_reboot&gt;</span></span>
<span class="line"><span>      &lt;on_crash&gt;destroy&lt;/on_crash&gt;</span></span>
<span class="line"><span>      &lt;devices&gt;</span></span>
<span class="line"><span>        &lt;emulator&gt;/usr/bin/kvm&lt;/emulator&gt;</span></span>
<span class="line"><span>        &lt;disk type=&quot;file&quot; device=&quot;disk&quot;&gt;</span></span>
<span class="line"><span>          &lt;driver name=&quot;qemu&quot; type=&quot;raw&quot;/&gt;</span></span>
<span class="line"><span>          &lt;source file=&quot;/home/dev/images/alice.img&quot;/&gt;</span></span>
<span class="line"><span>          &lt;target dev=&quot;vda&quot; bus=&quot;virtio&quot;/&gt;</span></span>
<span class="line"><span>          &lt;address type=&quot;pci&quot; domain=&quot;0x0000&quot; bus=&quot;0x00&quot; slot=&quot;0x04&quot; function=&quot;0x0&quot;/&gt;</span></span>
<span class="line"><span>        &lt;/disk&gt;</span></span>
<span class="line"><span>        &lt;disk type=&quot;file&quot; device=&quot;cdrom&quot;&gt;</span></span>
<span class="line"><span>          &lt;driver name=&quot;qemu&quot; type=&quot;raw&quot;/&gt;</span></span>
<span class="line"><span>          &lt;source file=&quot;/home/dev/iso/CentOS-6.5-x86_64-minimal.iso&quot;/&gt;</span></span>
<span class="line"><span>          &lt;target dev=&quot;hdc&quot; bus=&quot;ide&quot;/&gt;</span></span>
<span class="line"><span>          &lt;readonly/&gt;</span></span>
<span class="line"><span>          &lt;address type=&quot;drive&quot; controller=&quot;0&quot; bus=&quot;1&quot; target=&quot;0&quot; unit=&quot;0&quot;/&gt;</span></span>
<span class="line"><span>        &lt;/disk&gt;</span></span>
<span class="line"><span>        &lt;interface type=&#39;bridge&#39;&gt;</span></span>
<span class="line"><span>          &lt;source bridge=&#39;br0&#39;/&gt;</span></span>
<span class="line"><span>          &lt;mac address=&quot;00:00:A3:B0:56:10&quot;/&gt;</span></span>
<span class="line"><span>        &lt;/interface&gt;</span></span>
<span class="line"><span>        &lt;controller type=&quot;ide&quot; index=&quot;0&quot;&gt;</span></span>
<span class="line"><span>          &lt;address type=&quot;pci&quot; domain=&quot;0x0000&quot; bus=&quot;0x00&quot; slot=&quot;0x01&quot; function=&quot;0x1&quot;/&gt;</span></span>
<span class="line"><span>        &lt;/controller&gt;</span></span>
<span class="line"><span>        &lt;input type=&#39;mouse&#39; bus=&#39;ps2&#39;/&gt;</span></span>
<span class="line"><span>        &lt;graphics type=&#39;vnc&#39; port=&#39;-1&#39; autoport=&quot;yes&quot; listen=&#39;0.0.0.0&#39;/&gt;</span></span>
<span class="line"><span>        &lt;console type=&#39;pty&#39;&gt;</span></span>
<span class="line"><span>          &lt;target port=&#39;0&#39;/&gt;</span></span>
<span class="line"><span>        &lt;/console&gt;</span></span>
<span class="line"><span>      &lt;/devices&gt;</span></span>
<span class="line"><span>    &lt;/domain&gt;</span></span></code></pre></div><p>上面的主機xml配置文件定義瞭如下的虛擬機內容。</p><ul><li><p>1GB內存，一個虛擬cpu和一個硬件驅動</p></li><li><p>磁盤鏡像：<code>/home/dev/images/alice.img</code></p></li><li><p>從 CD-ROM 引導（<code>/home/dev/iso/CentOS-6.5-x86_64-minomal.iso</code>）</p></li><li><p>網絡：一個橋接到 br0 的虛擬網卡</p></li><li><p>通過 VNC 遠程訪問</p></li></ul><p><code>&lt;uuid&gt;&lt;/uuid&gt;</code> 中的 UUID 字符串可以隨機生成。為了得到一個隨機的 uuid 字符串，你可能需要使用 uuid 命令列工具。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ sudo apt-get install uuid</span></span>
<span class="line"><span>    $ uuid</span></span></code></pre></div><p>生成一個主機 xml 配置文件的方式就是通過一個已經存在的虛擬機來導出它的 xml 配置文件。如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh dumpxml alice &gt; bob.xml</span></span></code></pre></div><p><img src="https://c2.staticflickr.com/6/5808/23968234602_25e8019ec8_c.jpg" alt=""></p><h3 id="第五步-使用命令列啓動虛擬機" tabindex="-1">第五步：使用命令列啓動虛擬機 <a class="header-anchor" href="#第五步-使用命令列啓動虛擬機" aria-label="Permalink to “第五步：使用命令列啓動虛擬機”">​</a></h3><p>在啓動虛擬機之前，我們需要創建它的初始磁盤鏡像。為此，你需要使用 qemu-img 命令來生成一個 qemu-kvm 鏡像。下面的命令將會創建 10 GB 大小的空磁盤，並且它是 qcow2 格式的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ qemu-img create -f qcow2 /home/dev/images/alice.img 10G</span></span></code></pre></div><p>使用 qcow2 格式的磁盤鏡像的好處就是它在創建之初並不會給它分配全部大小磁盤容量（這裏是 10 GB），而是隨着虛擬機中文件的增加而逐漸增大。因此，它對空間的使用更加有效。</p><p>現在，你可以通過使用之前創建的 xml 配置文件啓動你的虛擬機了。下面的命令將會創建一個虛擬機，然後自動啓動它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh create alice.xml</span></span>
<span class="line"><span>    Domain alice created from alice.xml</span></span></code></pre></div><p><strong>注意</strong>: 如果你對一個已經存在的虛擬機執行了了上面的命令，那麼這個操作將會在沒有任何警告的情況下抹去那個已經存在的虛擬機的全部信息。如果你已經創建了一個虛擬機，你可能會使用下面的命令來啓動虛擬機。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh start alice.xml</span></span></code></pre></div><p>使用如下命令確認一個新的虛擬機已經被創建併成功的被啓動。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh list</span></span></code></pre></div><pre><code> Id    Name                           State
----------------------------------------------------
 3     alice                          running
</code></pre><p>同樣，使用如下命令確認你的虛擬機的虛擬網卡已經被成功的添加到了你先前創建的 br0 網橋中。</p><pre><code>$ sudo brctl show
</code></pre><p><img src="https://c2.staticflickr.com/2/1546/23449585383_a371e9e579_c.jpg" alt=""></p><h3 id="遠程連接虛擬機" tabindex="-1">遠程連接虛擬機 <a class="header-anchor" href="#遠程連接虛擬機" aria-label="Permalink to “遠程連接虛擬機”">​</a></h3><p>為了遠程訪問一個正在運行的虛擬機的控制台，你可以使用VNC客户端。</p><p>首先，你需要使用如下命令找出用於虛擬機的VNC端口號。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ sudo netstat -nap | egrep &#39;(kvm|qemu)&#39;</span></span></code></pre></div><p><img src="https://c2.staticflickr.com/6/5633/23448144274_49045bc868_c.jpg" alt=""></p><p>在這個例子中，用於 alice 虛擬機的 VNC 端口號是 5900。 然後啓動一個VNC客户端，連接到一個端口號為5900的VNC服務器。在我們的例子中，虛擬機支持由CentOS光盤文件啓動。</p><p><img src="https://c2.staticflickr.com/2/1533/24076369675_99408972a4_c.jpg" alt=""></p><h3 id="使用-virsh-管理虛擬機" tabindex="-1">使用 virsh 管理虛擬機 <a class="header-anchor" href="#使用-virsh-管理虛擬機" aria-label="Permalink to “使用 virsh 管理虛擬機”">​</a></h3><p>下面列出了 virsh 命令的常規用法：</p><p>創建客户機並且啓動虛擬機：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh create alice.xml</span></span></code></pre></div><p>停止虛擬機並且刪除客户機：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh destroy alice</span></span></code></pre></div><p>關閉虛擬機（不用刪除它）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh shutdown alice</span></span></code></pre></div><p>暫停虛擬機：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh suspend alice</span></span></code></pre></div><p>恢復虛擬機：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh resume alice</span></span></code></pre></div><p>訪問正在運行的虛擬機的控制台：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh console alice</span></span></code></pre></div><p>設置虛擬機開機啓動：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh autostart alice</span></span></code></pre></div><p>查看虛擬機的詳細信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh dominfo alice</span></span></code></pre></div><p>編輯虛擬機的配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh edit alice</span></span></code></pre></div><p>上面的這個命令將會使用一個默認的編輯器來調用主機配置文件。該配置文件中的任何改變都將自動被libvirt驗證其正確性。</p><p>你也可以在一個virsh會話中管理虛擬機。下面的命令會創建並進入到一個virsh會話中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    $ virsh</span></span></code></pre></div><p>在 virsh 提示中，你可以使用任何 virsh 命令。</p><p><img src="https://c2.staticflickr.com/6/5645/23708565129_b1ef968b30_c.jpg" alt=""></p><h3 id="問題處理" tabindex="-1">問題處理 <a class="header-anchor" href="#問題處理" aria-label="Permalink to “問題處理”">​</a></h3><ol><li><p>我在創建虛擬機的時候遇到了一個錯誤：</p><p>error: internal error: no supported architecture for os type &#39;hvm&#39;</p></li></ol><p>如果你的硬件不支持虛擬化的話你可能就會遇到這個錯誤。（例如，Intel VT或者AMD-V），這是運行KVM所必需的。如果你遇到了這個錯誤，而你的cpu支持虛擬化，那麼這裏可以給你一些可用的解決方案：</p><p>首先，檢查你的內核模組是否丟失。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  $ lsmod | grep kvm</span></span></code></pre></div><p>如果內核模組沒有加載，你必須按照如下方式加載它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  $ sudo modprobe kvm_intel (for Intel processor)</span></span>
<span class="line"><span>  $ sudo modprobe kvm_amd (for AMD processor)</span></span></code></pre></div><p>第二個解決方案就是添加 <code>--connect qemu:///system</code> 參數到 <code>virsh</code> 命令中，如下所示。當你正在你的硬件平台上使用超過一個虛擬機管理器的時候就需要添加這個參數（例如，VirtualBox，VMware）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  $ virsh --connect qemu:///system create alice.xml</span></span></code></pre></div><ol start="2"><li>當我試着訪問我的虛擬機的登陸控制台的時候遇到了錯誤：</li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>   $ virsh console alice</span></span>
<span class="line"><span>   error: internal error: cannot find character device &lt;null&gt;</span></span></code></pre></div><p>這個錯誤發生的原因是你沒有在你的虛擬機配置文件中定義控制台設備。在 xml 文件中加上下面的內部設備部分即可。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  &lt;console type=&#39;pty&#39;&gt;</span></span>
<span class="line"><span>    &lt;target port=&#39;0&#39;/&gt;</span></span>
<span class="line"><span>  &lt;/console&gt;</span></span></code></pre></div><hr>`,78)),n("p",null,[s[6]||(s[6]=a("via: ",-1)),e(i,{href:"http://xmodulo.com/use-kvm-command-line-debian-ubuntu.html"},{default:t(()=>[...s[5]||(s[5]=[a("http://xmodulo.com/use-kvm-command-line-debian-ubuntu.html",-1)])]),_:1})]),n("p",null,[s[10]||(s[10]=a("作者：",-1)),e(i,{href:"http://xmodulo.com/author/nanni"},{default:t(()=>[...s[7]||(s[7]=[a("Dan Nanni",-1)])]),_:1}),s[11]||(s[11]=a(" 譯者：",-1)),e(i,{href:"https://github.com/kylepeng93"},{default:t(()=>[...s[8]||(s[8]=[a("kylepeng93",-1)])]),_:1}),s[12]||(s[12]=a(" 校對：",-1)),e(i,{href:"https://github.com/oska874"},{default:t(()=>[...s[9]||(s[9]=[a("Ezio",-1)])]),_:1})]),n("p",null,[s[15]||(s[15]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:t(()=>[...s[14]||(s[14]=[a("Linux中國",-1)])]),_:1}),s[17]||(s[17]=a(" 榮譽推出",-1))])])}const C=p(h,[["render",c]]);export{y as __pageData,C as default};
